/bin/zsh -lc "cat > record-pip.cjs <<'EOF'
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
 const browser = await chromium.launch({headless:true, args:['--enable-webgl','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']});
 const page = await browser.newPage({viewport:{width:1280,height:720},acceptDownloads:true});
 page.on('pageerror', e=>console.log('PAGE ERROR',e.message));
 await page.goto('http://127.0.0.1:8739/');
 await page.waitForFunction(()=>window.__robotforge);
 await page.waitForTimeout(2000);
 console.log(await page.evaluate(()=>Object.keys(window.__robotforge)));
 await page.screenshot({path:'viewer-check.png'});
 fs.writeFileSync('browser-ready','ready');
 await page.click('#btn-record');
 console.log('RECORDING');
 while("'!fs.existsSync('"'stop-recording')) await page.waitForTimeout(200);
 const downloadPromise=page.waitForEvent('download');
 await page.click('#btn-record');
 const download=await downloadPromise;
 const name=download.suggestedFilename();
 await download.saveAs('pip-original.'+name.split('.').pop());
 console.log('SAVED',name);
 await browser.close();
})();
EOF
node record-pip.cjs"
